from pathlib import Path
import json,html
root=Path(__file__).resolve().parents[1]
docs=root/'public/en/lab/ecommerce-api/docs';docs.mkdir(parents=True,exist_ok=True)
error={'type':'object','required':['error'],'properties':{'error':{'type':'object','required':['code','message','details'],'properties':{'code':{'type':'string'},'message':{'type':'string'},'details':{'type':'object','additionalProperties':True}}}}}
variant={'type':'object','required':['id','label','sku','price_cents','stock'],'properties':{'id':{'type':'integer'},'label':{'type':'string'},'sku':{'type':'string'},'price_cents':{'type':'integer','minimum':0},'stock':{'type':'integer','minimum':0}}}
product={'type':'object','required':['id','name','category','description','image','currency','variants','price_from_cents','total_stock'],'properties':{'id':{'type':'integer'},'name':{'type':'string'},'category':{'type':'string','enum':['accessories','electronics','workspace']},'description':{'type':'string'},'image':{'type':'string'},'currency':{'type':'string','enum':['USD']},'variants':{'type':'array','items':{'$ref':'#/components/schemas/Variant'}},'price_from_cents':{'type':'integer'},'total_stock':{'type':'integer'}}}
cart_item={'type':'object','required':['id','product_id','variant_id','quantity','product_name','variant_label','unit_price_cents','subtotal_cents','available_stock'],'properties':{k:{'type':'string' if k in ['product_name','variant_label'] else 'integer'} for k in ['id','product_id','variant_id','quantity','product_name','variant_label','unit_price_cents','subtotal_cents','available_stock']}}
cart={'type':'object','required':['items','quantity','total_cents','currency'],'properties':{'items':{'type':'array','items':{'$ref':'#/components/schemas/CartItem'}},'quantity':{'type':'integer'},'total_cents':{'type':'integer'},'currency':{'type':'string','enum':['USD']}}}
order={'type':'object','required':['id','reference','status','delivery_method','currency','total_cents','items','created_at','demo_only'],'properties':{'id':{'type':'integer'},'reference':{'type':'string'},'status':{'type':'string','enum':['demo_created']},'delivery_method':{'type':'string','enum':['demo_pickup','demo_shipping']},'currency':{'type':'string','enum':['USD']},'total_cents':{'type':'integer'},'items':{'type':'array','items':{'$ref':'#/components/schemas/CartItem'}},'created_at':{'type':'string','format':'date-time'},'demo_only':{'type':'boolean','enum':[True]}}}
envelope=lambda key,ref:{'type':'object','required':['data'],'properties':{'data':{'type':'object','required':[key],'properties':{key:{'$ref':'#/components/schemas/'+ref}}}}}
success_schemas={'Products':{'type':'object','required':['data','meta'],'properties':{'data':{'type':'array','items':{'$ref':'#/components/schemas/Product'}},'meta':{'type':'object','required':['page','per_page','total','total_pages','sort'],'properties':{k:{'type':'string' if k=='sort' else 'integer'} for k in ['page','per_page','total','total_pages','sort']}}}},'ProductResponse':{'type':'object','required':['data'],'properties':{'data':{'$ref':'#/components/schemas/Product'}}},'CartResponse':envelope('cart','Cart'),'OrderResponse':envelope('order','Order'),'ResetResponse':{'type':'object','required':['data'],'properties':{'data':{'type':'object','required':['reset','cart'],'properties':{'reset':{'type':'boolean'},'cart':{'$ref':'#/components/schemas/Cart'}}}}}}
success_schemas['OrderResponse']['properties']['data']['properties']['replayed']={'type':'boolean'}
defs={'Error':error,'Variant':variant,'Product':product,'CartItem':cart_item,'Cart':cart,'Order':order,**success_schemas}
number=lambda maximum:{'type':'integer','minimum':1,'maximum':maximum}
endpoints=[
('get','/products','List, filter and sort products','Products',None,{'page':'Positive page number (1–100).','per_page':'Items per page (1–12, default 6).','q':'Search name and description, up to 80 characters.','category':'accessories, electronics or workspace.','in_stock':'true or false.','sort':'name_asc, price_asc or price_desc.'}),
('get','/products/{id}','Get a product and its offers','ProductResponse',None,{}),
('get','/cart','Get your current cart and CSRF header','CartResponse',None,{}),
('post','/cart/items','Add an offer or merge its quantity','CartResponse',{'product_id':number(100000),'variant_id':number(100000),'quantity':number(20)},{}),
('patch','/cart/items/{id}','Set an existing cart item’s quantity','CartResponse',{'quantity':number(20)},{}),
('delete','/cart/items/{id}','Remove an existing cart item','CartResponse',None,{}),
('post','/orders','Create an isolated demo order','OrderResponse',{'delivery_method':{'type':'string','enum':['demo_pickup','demo_shipping']},'demo_acknowledged':{'type':'boolean','enum':[True]}},{}),
('get','/orders/{id}','Get an order from your sandbox','OrderResponse',None,{}),
('post','/reset','Restore your stock, cart and orders','ResetResponse',{},{}),
]
spec={'openapi':'3.0.3','info':{'title':'E-commerce API Demo','version':'1.0.0','description':'Original PHP sandbox with fictional catalog data. Browser cookies isolate stock, carts and orders. No payments or external business systems.'},'servers':[{'url':'/api/demo/v1'}],'paths':{},'components':{'schemas':defs,'securitySchemes':{'csrf':{'type':'apiKey','in':'header','name':'X-CSRF-Token','description':'Read from any API response header, normally GET /cart. Same-origin session cookie is also required.'}}}}
cards=[]
for method,path,summary,schema,body,queries in endpoints:
    operation={'summary':summary,'operationId':method+path.replace('/','_').replace('{id}','id'),'responses':{'200':{'description':'Successful response (also idempotent replay or merge)','headers':{'X-CSRF-Token':{'schema':{'type':'string'},'description':'Session CSRF token; retain for mutations'}},'content':{'application/json':{'schema':{'$ref':'#/components/schemas/'+schema}}}}},'parameters':[]}
    if method=='post' and path in ['/orders','/cart/items']:operation['responses']['201']={'description':'Created','content':{'application/json':{'schema':{'$ref':'#/components/schemas/'+schema}}}}
    for status in [400,403,404,405,409,413,415,422,429,503]:operation['responses'][str(status)]={'description':{400:'Malformed JSON',403:'Invalid origin or CSRF token',404:'Missing resource',405:'Wrong method',409:'Stock, empty-cart, order limit or idempotency conflict',413:'Body exceeds 8 KB',415:'Wrong content type',422:'Input validation',429:'Rate or sandbox capacity limit',503:'Temporary storage failure'}[status],'content':{'application/json':{'schema':{'$ref':'#/components/schemas/Error'}}}}
    if '{id}' in path:operation['parameters'].append({'name':'id','in':'path','required':True,'schema':{'type':'integer','minimum':1}})
    for name,description in queries.items():operation['parameters'].append({'name':name,'in':'query','description':description,'schema':{'type':'integer','minimum':1,'maximum':100 if name=='page' else 12} if name in ['page','per_page'] else {'type':'string'}})
    if method in ['post','patch','delete']:operation['security']=[{'csrf':[]}]
    if path=='/orders' and method=='post':operation['parameters'].append({'name':'Idempotency-Key','in':'header','required':True,'schema':{'type':'string','pattern':'^[a-zA-Z0-9_-]{8,80}$'}})
    if body is not None:operation['requestBody']={'required':True,'content':{'application/json':{'schema':{'type':'object','required':list(body),'additionalProperties':False,'properties':body}}}}
    spec['paths'].setdefault(path,{})[method]=operation
    example={'product_id':1,'variant_id':11,'quantity':1} if path=='/cart/items' else {'quantity':2} if method=='patch' else {'delivery_method':'demo_pickup','demo_acknowledged':True} if path=='/orders' else {} if path=='/reset' else None
    querytable=''.join(f'<tr><td><code>{name}</code></td><td>{description}</td></tr>' for name,description in queries.items())
    examplehtml=f'<pre class="json-block" tabindex="0">{html.escape(json.dumps(example,indent=2))}</pre>' if example is not None else ''
    cards.append(f'<article class="endpoint"><h2><code>{method.upper()} /api/demo/v1{html.escape(path)}</code></h2><p>{summary}.</p>'+('<table class="doc-table"><tbody>'+querytable+'</tbody></table>' if querytable else '')+examplehtml+'</article>')
(docs/'openapi.json').write_text(json.dumps(spec,indent=2),encoding='utf8')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>E-commerce API Documentation | Nikita Zalesskiy</title><meta name="description" content="Endpoints, validation, stock conflicts and idempotent checkout for the PHP e-commerce demo API."><link rel="canonical" href="https://nikitazalesskiy.ru/en/lab/ecommerce-api/docs/"><meta property="og:title" content="E-commerce API Documentation"><meta property="og:description" content="Endpoints, validation and examples for an original PHP sandbox."><meta property="og:type" content="website"><meta property="og:locale" content="en_US"><meta property="og:url" content="https://nikitazalesskiy.ru/en/lab/ecommerce-api/docs/"><meta property="og:image" content="https://nikitazalesskiy.ru/en/lab/ecommerce-api/assets/demo-cover.png"><link rel="stylesheet" href="../assets/app.css"><script type="module" src="docs.js"></script></head><body><a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="container header-inner"><a class="brand" href="https://nikitazalesskiy.ru/en/"><span class="mark">NZ</span><span>Nikita Zalesskiy</span></a><nav class="header-links" aria-label="Primary navigation"><a href="../">Playground</a><a href="https://github.com/HUKUTOS2505/ecommerce-api-demo" target="_blank" rel="noopener noreferrer">Source ↗</a><span style="white-space:nowrap"><a href="https://nikitazalesskiy.ru/" lang="ru" aria-label="Russian version">RU</a> | <a href="https://nikitazalesskiy.ru/en/" lang="en" aria-label="English portfolio">EN</a></span></nav></div></header><main id="main" class="container docs"><p class="eyebrow">API Documentation</p><h1>E-commerce REST API</h1><p class="lead">Nine endpoints, one isolated sandbox. Product prices use integer cents. Cart items do not reserve stock; checkout checks stock again and reduces only your sandbox inventory.</p><div class="docs-navigation"><a class="button" href="../">Open Playground</a><a class="button" href="openapi.json">OpenAPI 3.0 JSON</a></div><div class="notice">No account, payment or personal details are needed. State expires after one hour of inactivity. Reset removes your cart and demo orders and restores your stock.</div><section class="panel"><h2>Try a real request</h2><p>These read-only examples use your current sandbox and show the actual HTTP response.</p><label class="field">Endpoint<select id="try-path"><option value="/products?page=1&amp;per_page=3&amp;sort=price_asc">Sorted catalog</option><option value="/products/1">Product and variants</option><option value="/cart">Current cart</option><option value="/products/999999">Missing product (404)</option><option value="/products?page=0">Invalid page (422)</option></select></label><div class="actions"><button id="try-request" class="button primary">Send GET Request</button></div><p id="try-status" role="status"></p><pre id="try-json" class="json-block" tabindex="0">The JSON response will appear here.</pre></section><h2 style="margin-top:40px">Session and mutation requests</h2><p>Keep the <code>ecommerce_demo</code> HttpOnly cookie. Read <code>X-CSRF-Token</code> from GET /cart and send it as a header for POST, PATCH and DELETE. Write requests require the same origin. JSON bodies are limited to 8 KB and must use <code>Content-Type: application/json</code>.</p><p>POST /orders also needs <code>Idempotency-Key</code>. Repeating the same key and payload returns the original order without reducing stock again. Reusing the key with a different payload returns 409. A reset clears these keys with your orders.</p>'''+''.join(cards)+'''<section class="endpoint"><h2>Errors and limits</h2><p>400: malformed JSON · 403: CSRF/origin · 404: missing resource · 405: wrong method · 409: stock/cart/idempotency conflict · 413: payload size · 415: content type · 422: validation · 429: rate limit · 503: temporary storage error.</p><p>Quantities are integers from 1 to 20. A sandbox holds at most 20 orders. There are at most 1,000 active sandboxes. Limits are 120 requests per minute per sandbox and 300 per server-observed IP. Rate-limited responses include <code>Retry-After: 60</code>.</p><pre class="json-block" tabindex="0">{
  "error": {
    "code": "insufficient_stock",
    "message": "Not enough stock for this variant.",
    "details": { "available_stock": 0, "cart_quantity": 0 }
  }
}</pre><p>No arbitrary SQL, file uploads, customer credentials or external business-system connections are accepted.</p></section></main><footer class="footer"><div class="container"><a href="../">Back to the playground</a></div></footer></body></html>'''
(docs/'index.html').write_text(page,encoding='utf8')
print('OpenAPI schema and English documentation generated')
